import { scriptedModel } from './test/helpers/mock-model.js';
import { summarizeThread, answerAboutOrders, classifyTicket, continueChat } from './src/legacy/assistant.js';

// Test summarizeThread
const summarizeModel = scriptedModel([
  { text: 'Order is processing.', usage: [50, 10] },
]);

const thread = [
  { from: 'customer', text: 'Where is my order?' },
  { from: 'agent', text: 'Let me check.' },
];

const summary = await summarizeThread(summarizeModel, thread);
console.log('✓ summarizeThread:', summary);

// Test classifyTicket
const classifyModel = scriptedModel([
  { text: JSON.stringify({ category: 'shipping', urgent: true }), usage: [40, 15] },
]);

const classification = await classifyTicket(classifyModel, 'My package never arrived');
console.log('✓ classifyTicket:', classification);

// Test answerAboutOrders
const answerModel = scriptedModel([
  { toolCalls: [{ name: 'orderLookup', input: { orderId: 'A100' } }], usage: [60, 8] },
  { text: 'Your order A100 is shipped.', usage: [80, 12] },
]);

const answer = await answerAboutOrders(answerModel, 'What is the status of my order?', { customerId: 'C1' });
console.log('✓ answerAboutOrders:', answer);

console.log('\n✓ All functions migrated successfully!');
EOF
